  if(action==='category-tab'){state.categoryTab=el.dataset.tab;await refreshViewData();renderPage();$(`[data-action="category-tab"][data-tab="${state.categoryTab}"]`)?.focus({preventScroll:true});return;}
  if(action==='new-category')return openModal('category');
  if(action==='category-save'){
   const name=$('#kkf-category-name').value.trim(),short=$('#kkf-category-short').value.trim().toUpperCase(),period=$('#kkf-category-period').value.trim();if(name.length<3||!short||!period)throw new Error('Isi nama minimal 3 karakter, singkatan, dan periode.');const c={id:M.uid('C'),name,short,period,description:$('#kkf-category-description').value.trim(),color:$('#kkf-category-color').value,icon:'book'};await remote.category(c);state.categoryId=c.id;state.categoryTab='sessions';closeModal();await navigate('categories');toast('Kategori sudah dibuat.');return;
  }
  if(action==='new-session'){if(!category())return openModal('category');return startBuilder();}
  if(action==='modal-close')return closeModal();
  if(action==='manage-session')return openModal('manage',{sessionId:el.dataset.id});
  if(action==='manage-edit'){const s=M.copy(M.getSession(store,el.dataset.id));closeModal();return startBuilder(s);}
  if(action==='manage-duplicate'){const s=M.copy(M.getSession(store,el.dataset.id));s.id=M.uid('S');s.revision=0;s.title+=' — salinan';s.sequence=store.sessions.filter(x=>x.categoryId===s.categoryId).length+1;s.slug=store.categories.find(c=>c.id===s.categoryId).short.toLowerCase()+String(s.sequence).padStart(2,'0');s.status='DRAFT';s.released=false;s.opensAt=null;s.closesAt=null;s.questionList.forEach(q=>{q.id=M.uid('Q');});closeModal();return startBuilder(s);}
