  if(action==='refresh-live'){if(state.mode==='owner'){const firstLoad=!!state.loadError;if(firstLoad){state.loading=true;state.loadError='';renderPage();}try{await remote.refreshOwner();await refreshViewData();state.loading=false;state.loadError='';renderPage();}catch(e){if(firstLoad){state.loading=false;state.loadError=e.message;renderPage();return;}throw e;}}else{if(state.auth){await flushDraft();await remote.refreshParticipant();}else await remote.publicSession();renderPublic();}toast('Data diperbarui.');return;}
  if(action==='session-public'||action==='manage-preview'){const s=M.getSession(store,el.dataset.id||store.activeSessionId);if(!s?.slug)throw new Error('Aktifkan tautan tugas terlebih dahulu.');win.open('/'+s.slug,'_blank','noopener');return;}
  if(action==='manage-close'||action==='manage-release'||action==='manage-reopen'){const command={'manage-close':'close','manage-release':'release','manage-reopen':'reopen'}[action],value={};if(command==='reopen'){const d=$('#kkf-reopen-deadline').value;if(!d)throw new Error('Isi tenggat baru untuk membuka kembali sesi.');value.closesAt=new Date(d+':00+07:00').toISOString();}await remote.control(el.dataset.id,command,value);closeModal();renderPage();toast('Status sesi diperbarui.');return;}
  if(action==='manage-link'){const s=M.getSession(store,el.dataset.id),code=$('#kkf-retry-alias').value.trim().toLowerCase();await remote.attachLink(s,code);closeModal();renderPage();toast('Tautan sudah aktif: klasku.my.id/'+code);return;}
  if(action==='manage-rekey'){const s=M.getSession(store,el.dataset.id),q=s.questionList.find(q=>!['ESSAY','SURVEY'].includes(q.kind));if(!q)throw new Error('Sesi ini tidak memiliki kunci objektif.');state.builder=M.copy(s);state.questionIndex=s.questionList.indexOf(q);state.modal={type:'rekey',sessionId:s.id};renderModal();return;}
