  if(action==='assignment-save'){await remote.assign(state.builder.id,state.builder.participants);closeModal();renderPage();toast('Penugasan peserta diperbarui.');return;}
  if(action==='result-control-open'){const sub=store.submissions.find(s=>s.id===state.modal.submissionId);return openModal('result-control',{submissionId:sub.id,command:sub.status==='VOID'?'restore':'void',revision:sub.revision});}
  if(action==='result-control-save'){await remote.resultControl(state.modal.submissionId,state.modal.command,$('#kkf-result-reason').value,state.modal.revision);closeModal();renderPage();toast('Status pengumpulan dan poin diperbarui.');return;}
  if(action==='rekey-save'){const b=state.builder,q=b.questionList[state.questionIndex];await remote.rekey(b.id,q.id,{correct:q.correct,accepted:q.accepted,number:q.number,tolerance:q.tolerance,ignoreCase:q.ignoreCase,collapseSpaces:q.collapseSpaces});closeModal();renderPage();toast('Kunci dikoreksi. Selisih nilai dan poin telah dihitung ulang.');return;}
  if(action==='builder-step'||action==='builder-next'||action==='builder-prev'){state.builderStep=action==='builder-step'?Number(el.dataset.step):Math.max(0,Math.min(4,state.builderStep+(action==='builder-next'?1:-1)));renderModal();return;}
  if(action==='builder-question'){state.questionIndex=Number(el.dataset.index);renderModal();return;}
  if(action==='builder-add-question'){state.builder.questionList.push(M.blankQuestion($('#kkf-new-question-kind').value));state.questionIndex=state.builder.questionList.length-1;renderModal();return;}
  if(action==='builder-delete-question'){if(state.builder.questionList.length<=1)return;state.builder.questionList.splice(state.questionIndex,1);state.questionIndex=Math.max(0,state.questionIndex-1);renderModal();return;}
  if(action==='builder-add-option'){state.builder.questionList[state.questionIndex].options.push('');renderModal();return;}
  if(action==='builder-delete-option'){const q=state.builder.questionList[state.questionIndex],i=Number(el.dataset.index);q.options.splice(i,1);if(q.kind==='MULTI')q.correct=q.correct.filter(k=>k!==i).map(k=>k>i?k-1:k);else q.correct=q.correct===i?0:q.correct>i?q.correct-1:q.correct;renderModal();return;}
  if(action==='builder-pick-all'){state.builder.participants=state.builder.participants.length===store.participants.length?[]:store.participants.map(p=>p.id);renderModal();return;}
  if(action==='builder-save'||action==='builder-publish'){
   const b=state.builder;b.title=b.title.trim();b.slug=b.slug.trim().toLowerCase();if(b.title.length<3)throw new Error('Isi judul minimal 3 karakter untuk menyimpan draf.');if(action==='builder-publish'){const errors=M.validateSession(b,store);if(errors.length)throw new Error(errors.join(' '));b.status='PUBLISHED';}else b.status='DRAFT';
   await remote.saveSession(b,action==='builder-publish');state.categoryId=b.categoryId;state.categoryTab='sessions';closeModal();await navigate('categories');toast(action==='builder-publish'?'Sesi diterbitkan. Tautan siap dibagikan.':'Draf tersimpan di server.');return;
  }
  if(action==='import-open'){state.importText='';state.importPreview=null;return openModal('import');}
  if(action==='import-sample'){state.importText='Nama\tKelompok\tPassword awal\nKirana Amalia\tESY 2026\tKirana123!\nDaffa Prakoso\tESY 2026\t\nNadira Putri\tKelompok C\tNadira123!';state.importPreview=null;renderModal();return;}
  if(action==='import-template')return copyText('Nama\tKelompok\tPassword awal\tparticipant_id\nKirana Amalia\tESY 2026\tKirana123!\t');
  if(action==='import-preview'){state.importText=$('#kkf-import-text').value;state.importPreview=M.previewImport(store,state.importText);renderModal();return;}
  if(action==='import-commit'){const result=await remote.importRows(state.importPreview);state.importText='';state.importPreview=null;closeModal();navigate('participants');toast(`${result.added} peserta ditambahkan; ${result.updated} diperbarui. Password lama dipertahankan.`);return;}
  if(action==='reset-open')return openModal('reset',{participantId:el.dataset.id});
  if(action==='reset-save'){const id=state.modal.participantId,password=$('#kkf-reset-password').value;if(password&&M.passwordProblem(password))throw new Error(M.passwordProblem(password));await remote.reset(id,password);closeModal();renderPage();toast('Akses direset. Identitas dan riwayat tetap ada.');return;}
  if(action==='review-open'){const sub=await remote.submission(el.dataset.id);return openModal('review',{submissionId:sub.id,expectedRevision:sub.revision,essayScores:M.copy(sub.essayScores||{})});}
  if(action==='review-save'){await remote.grade(state.modal.submissionId,state.modal.essayScores,state.modal.expectedRevision);closeModal();renderPage();toast('Penilaian disimpan. Selisih poin sudah dihitung.');return;}
  if(action==='export-copy'){const x=state.exportSnapshot;return copyText(x.rows.map(r=>r.map(v=>String(v).replace(/[\t\r\n]/g,' ')).join('\t')).join('\n'));}
  if(action==='export-csv')return downloadCsv();
  if(action==='export-xlsx')return downloadExcel();
  if(action==='public-tab')return publicTab(el.dataset.tab);
  if(action==='login-open'){state.loginQuery='';state.loginSelected=null;return openModal('login');}
  if(action==='login-pick'){state.loginSelected=el.dataset.id;$('#kkf-login-access').innerHTML=loginAccessFields();$('#kkf-login-results').innerHTML=loginResults();$('[data-action="login-submit"]').disabled=false;($('#kkf-login-password')||$('#kkf-new-password'))?.focus({preventScroll:true});return;}
  if(action==='login-submit'){if(!state.loginSelected)throw new Error('Pilih nama terlebih dahulu.');const auth=await remote.login(state.loginSelected,$('#kkf-login-password')?.value||'',$('#kkf-new-password')?.value||'',$('#kkf-confirm-password')?.value||'');state.auth=auth;state.idempotencyKey=M.uid('IK');const draft=M.getDraft(store,auth.sessionId,auth.participantId);state.answers=draft?M.copy(draft.answers):{};state.draftRevision=draft?.revision||0;state.draftDirty=false;state.publicTab=subForAuth()?'result':'answers';closeModal();renderPublicTab();toast('Akses terbuka. Selamat mengerjakan.');return;}
