  if(action==='review-answers'){if(!state.auth)return act('login-open',el);await flushDraft();const missing=M.missingAnswers(activeSession(),state.answers);$$('.kkf-question-card').forEach(card=>card.classList.toggle('is-missing',missing.some(q=>q.id===card.dataset.questionId)));if(missing.length){const first=missing[0],card=$(`.kkf-question-card[data-question-id="${first.id}"]`);card?.scrollIntoView?.({behavior:'smooth',block:'start'});$('input,textarea',card)?.focus({preventScroll:true});toast(`Masih ada ${missing.length} soal wajib yang belum diisi.`);return;}return openModal('confirm-submit');}
