  if(el.id==='kkf-export-group'){state.participantGroup=el.value;await refreshViewData();renderPage();return;}
  if(el.id==='kkf-period-select'){state.periodByCategory[state.categoryId]=el.value;await refreshViewData();renderPage();return;}
  if(el.id==='kkf-rank-scope'){state.rankScope=el.value;await refreshViewData();renderPage();return;}
  if(el.id==='kkf-rank-session'){state.rankSessionId=el.value;await refreshViewData();renderPage();return;}
  if(el.id==='kkf-public-rank-scope'){state.rankScope=el.value;await remote.ranking(state.rankScope);renderPublicTab();return;}
