  if(el.dataset.builderParticipant){const ids=new Set(state.builder.participants);el.checked?ids.add(el.dataset.builderParticipant):ids.delete(el.dataset.builderParticipant);state.builder.participants=[...ids];$('#kkf-selected-count').textContent=ids.size;return;}
  if(el.dataset.keyIndex!==undefined){const q=state.builder.questionList[state.questionIndex],i=Number(el.dataset.keyIndex);if(q.kind==='MULTI'){const keys=new Set(q.correct);el.checked?keys.add(i):keys.delete(i);q.correct=[...keys];}else q.correct=i;return;}
