 async function dispatch(action,el){if(busy||disposed||(state.loading&&action!=='exit-workspace'))return;busy=true;root.setAttribute('aria-busy','true');if(el)el.disabled=true;try{return await act(action,el);}finally{busy=false;root.removeAttribute('aria-busy');if(el?.isConnected)el.disabled=false;}}
 const clickHandler=e=>{const el=e.target.closest?.('[data-action]');if(!el||!root.contains(el)||el.disabled)return;e.preventDefault();Promise.resolve(dispatch(el.dataset.action,el)).catch(error);};
 const inputHandler=e=>{const el=e.target;if(!el.matches?.('select,input[type="checkbox"],input[type="radio"]')){try{inputChanged(el);}catch(err){error(err);}}};
