  if(e.key==='Enter'&&dialog?.open&&e.target.matches('input:not([type=checkbox]):not([type=radio])')){const action={login:'login-submit','confirm-submit':'submit-final',category:'category-save',reset:'reset-save'}[state.modal?.type];if(action){e.preventDefault();const button=$(`[data-action="${action}"]`,dialog);if(button&&!button.disabled)Promise.resolve(dispatch(action,button)).catch(error);}return;}
  if(['ArrowRight','ArrowLeft','Home','End'].includes(e.key)&&e.target.getAttribute?.('role')==='tab'){const list=e.target.closest('[role="tablist"]'),items=$$('[role="tab"]',list),index=items.indexOf(e.target),next=e.key==='Home'?0:e.key==='End'?items.length-1:(index+(e.key==='ArrowRight'?1:-1)+items.length)%items.length;e.preventDefault();items[next].click();const replacements=$$('[role="tablist"]').find(x=>x.getAttribute('aria-label')===list.getAttribute('aria-label'));$$('[role="tab"]',replacements||list)[next]?.focus();}
