 return {store,state,render:renderPage,setLoadState({error=''}={}){if(disposed)return;state.loading=false;state.loadError=error;if(!state.categoryId)state.categoryId=store.categories[0]?.id||'';state.rankSessionId||=store.activeSessionId;renderPage();},dispose(){disposed=true;clearTimeout(searchTimer);clearTimeout(state.savingTimer);remote.dispose();state.answers={};state.auth=null;state.builder=null;state.importText='';clearTimeout(state.toastTimer);closeModal();root.removeEventListener('click',clickHandler);root.removeEventListener('input',inputHandler);root.removeEventListener('change',changeHandler);root.removeEventListener('keydown',keyHandler);root.innerHTML='';}};
